import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

function AdminPanel() {
  const navigate = useNavigate();

  const [questions, setQuestions] = useState([]);
  const [newQuestion, setNewQuestion] = useState('');
  const [selectedQuestionId, setSelectedQuestionId] = useState('');
  const [newChoice, setNewChoice] = useState('');
  const [choices, setChoices] = useState([]);

  const [feedbacks, setFeedbacks] = useState([]);

  useEffect(() => {
    if (localStorage.getItem('isAdmin') !== 'true') {
      navigate('/login');
    } else {
      fetchQuestions();
      fetchFeedbacks();
    }
  }, []);

  useEffect(() => {
    if (selectedQuestionId) {
      fetchChoices(selectedQuestionId);
    }
  }, [selectedQuestionId]);

  const fetchQuestions = () => {
    fetch('http://localhost:3001/api/questions')
      .then(res => res.json())
      .then(setQuestions);
  };

  const fetchFeedbacks = () => {
    fetch('http://localhost:3001/api/feedback')
      .then(res => res.json())
      .then(setFeedbacks);
  };

  const fetchChoices = (questionId) => {
    fetch(`http://localhost:3001/api/questions/${questionId}/choices`)
      .then(res => res.json())
      .then(setChoices);
  };

  const addQuestion = async () => {
    if (!newQuestion.trim()) return;
    await fetch('http://localhost:3001/api/admin/questions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ question_text: newQuestion, is_choice_based: true })
    });
    setNewQuestion('');
    fetchQuestions();
  };

  const deleteQuestion = async (id) => {
    await fetch(`http://localhost:3001/api/admin/questions/${id}`, {
      method: 'DELETE'
    });
    fetchQuestions();
  };

  const addChoice = async () => {
    if (!newChoice.trim() || !selectedQuestionId) return;
    await fetch('http://localhost:3001/api/admin/choices', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        questionId: selectedQuestionId,
        choiceText: newChoice
      })
    });
    setNewChoice('');
    fetchChoices(selectedQuestionId);
  };

  const deleteFeedback = async (id) => {
    await fetch(`http://localhost:3001/api/feedback/${id}`, {
      method: 'DELETE'
    });
    fetchFeedbacks();
  };

  const handleLogout = () => {
    localStorage.removeItem('isAdmin');
    navigate('/login');
  };

  return (
    <div style={{ padding: '2rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <h2>Админ-панель</h2>
        <button onClick={handleLogout}>Выйти</button>
      </div>

      {/* Добавление вопроса */}
      <div style={{ marginBottom: '1rem' }}>
        <input
          type="text"
          placeholder="Новый вопрос"
          value={newQuestion}
          onChange={(e) => setNewQuestion(e.target.value)}
        />
        <button onClick={addQuestion} style={{ marginLeft: '10px' }}>Добавить вопрос</button>
      </div>

      {/* Список вопросов */}
      <h3>Все вопросы:</h3>
      <ul>
        {questions.map(q => (
          <li key={q.id}>
            <strong>{q.id}</strong>: {q.question_text}
            <button onClick={() => deleteQuestion(q.id)} style={{ marginLeft: '10px' }}>Удалить</button>
          </li>
        ))}
      </ul>

      <hr />

      {/* Добавление вариантов */}
      <h3>Добавление вариантов ответа</h3>
      <div style={{ marginBottom: '1rem' }}>
        <label>Выберите вопрос:</label>
        <select
          value={selectedQuestionId}
          onChange={(e) => setSelectedQuestionId(e.target.value)}
        >
          <option value="">-- выбрать --</option>
          {questions
            .filter(q => q.is_choice_based)
            .map(q => (
              <option key={q.id} value={q.id}>
                {q.id} — {q.question_text}
              </option>
            ))}
        </select>
      </div>

      {selectedQuestionId && (
        <>
          <div>
            <input
              type="text"
              placeholder="Вариант ответа"
              value={newChoice}
              onChange={(e) => setNewChoice(e.target.value)}
            />
            <button onClick={addChoice} style={{ marginLeft: '10px' }}>
              Добавить вариант
            </button>
          </div>

          <h4>Текущие варианты:</h4>
          <ul>
            {choices.map(choice => (
              <li key={choice.id}>{choice.choice_text}</li>
            ))}
          </ul>
        </>
      )}

      <hr />

      {/* Список отзывов */}
      <h3>Отзывы</h3>
      <ul>
        {feedbacks.map(f => (
          <li key={f.id}>
            <strong>{f.username || 'Аноним'}:</strong> {f.comment}
            <button onClick={() => deleteFeedback(f.id)} style={{ marginLeft: '10px' }}>
              Удалить
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default AdminPanel;
